// Public TL exposure programs for jointly keyed YM2151 operator phases.
package main
import("crypto/sha256";"encoding/json";"flag";"fmt";"os";"path/filepath")
type operation struct{Kind string `json:"kind"`;Reg int `json:"reg,omitempty"`;Value int `json:"value"`;Count int `json:"delay_count,omitempty"`;Role string `json:"role,omitempty"`}
type phase_fixture struct{Name string `json:"name"`;Order []string `json:"operator_order"`;Init string `json:"init"`;ModelInit string `json:"model_init"`;Event string `json:"event"`;InitHash string `json:"init_sha256"`;ModelHash string `json:"model_init_sha256"`;EventHash string `json:"event_sha256"`;InitOps []operation `json:"init_operations"`;ModelOps []operation `json:"model_init_operations"`;EventOps []operation `json:"event_operations"`;Stride int `json:"stride"`;Increment int `json:"recorded_increment_20bit"`;Frames int `json:"recorded_frames"`;HoldCount int `json:"hold_delay_count"`;MarkerCount int `json:"marker_delay_count"`;Exclusion int `json:"marker_exclusion_recorded_samples"`;ExpectedMarkers int `json:"expected_left_markers"`;ModelWait int `json:"conditioning_model_master_clocks"`;Prefix int `json:"model_prefix_delay_count"`;Preheat int `json:"preheat_delay_count"`;Notes []string `json:"notes"`}
func main(){output:=flag.String("output","","fresh directory");prefix:=flag.Int("prefix-delay",0,"model32-master-clock prefix,0or1only");preheat:=flag.Int("preheat",8192,"8192or16384delay counts");flag.Parse();if *output==""||flag.NArg()!=0||(*prefix!=0&&*prefix!=1)||(*preheat!=8192&&*preheat!=16384){fmt.Fprintln(os.Stderr,"use -output NEW_DIRECTORY");os.Exit(1)};e:=make_programs(*output,*prefix,*preheat);if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func make_programs(output string,prefix,preheat int)error{
 e:=os.Mkdir(output,0755);if e!=nil{return e};cases:=[]phase_fixture{};offset:=map[string]int{"M1":0,"M2":8,"C1":16,"C2":24}
 for _,order:=range [][]string{{"M1","M2","C1","C2","M1"},{"M1","C2","C1","M2","M1"},{"LEAK"}}{
  name:="phase-forward";markers:=len(order)-1;if len(order)==1{name="phase-leak"}else if order[1]=="C2"{name="phase-reverse"};c:=phase_fixture{Name:name,Order:order,Stride:8,Increment:32992,Frames:16384,HoldCount:24576,MarkerCount:1024,Exclusion:128,ExpectedMarkers:markers,ModelWait:1790016,Prefix:prefix,Preheat:preheat,Notes:[]string{"All4 keyed together and remain keyed; ALG7FB0noiseOFF; first/lastM1testsTLhistory","LEFTmarkers bound transitions; RIGHTis continuous PG timeline but may have a brief intentional tiny/zero TLallmuted interval inside excluded markers","Other3TL127leak measured,not assumed exactlyzero; phases are an independent diagnostic,never fitted away inside complexalgorithm outputs","Wrapper delaycount32master clocks only two nativeframe residues; no full64phase-coverage claim"}}
  init:=initialize();init=append(init,w(32,199,"ALG7FB0bothpan"),w(40,74,"KC4A"));for _,op:=range []string{"M1","M2","C1","C2"}{off:=offset[op];tl:=127;if op=="M1"&&len(order)>1{tl=0};init=append(init,w(64+off,0,"DT1zeroMUL0"),w(96+off,tl,"initialTLexposure"),w(128+off,31,"AR31KS0"),w(224+off,15,"RR15"))};init=append(init,w(8,120,"jointall4keyON"),d(preheat,"preheat"));model:=cleanup();model=append(model,d(55938,"modelconditioningwait"));if prefix>0{model=append(model,d(prefix,"model-start-grid probe;NOTacceptedbusphasecoverage"))};model=append(model,init...);event:=[]operation{}
  for i:=0;i<len(order)-1;i++{event=append(event,d(24576,"stableexposure"),w(32,135,"LEFTmarkerOFF"),d(256,"beforeTLchanges"),w(96+offset[order[i]],127,"muteOLDfirst"),w(96+offset[order[i+1]],0,"unmuteNEWsecond"),d(768,"restofmarker"),w(32,199,"LEFTmarkerRESTORE"))};event=append(event,d(24576,"returnM1hold"));c.InitOps=init;c.ModelOps=model;c.EventOps=event;c.Init=filepath.Join(output,name+"-init.bin");c.ModelInit=filepath.Join(output,name+"-model-init.bin");c.Event=filepath.Join(output,name+"-event.bin");a,b,x:=encode(init),encode(model),encode(event);c.InitHash=hash(a);c.ModelHash=hash(b);c.EventHash=hash(x)
  for p,b:=range map[string][]byte{c.Init:a,c.ModelInit:b,c.Event:x}{e=os.WriteFile(p,b,0600);if e!=nil{return e}};cases=append(cases,c)
 };b,e:=json.MarshalIndent(cases,"","  ");if e!=nil{return e};return os.WriteFile(filepath.Join(output,"cases.json"),append(b,'\n'),0600)
}
func cleanup()[]operation{out:=[]operation{w(15,0,"NEoff beforeRR/keyoff")};for r:=224;r<256;r++{out=append(out,w(r,15,"allRR15beforekeyoff"))};for ch:=0;ch<8;ch++{out=append(out,w(8,ch,"keyoff"))};return out}
func initialize()[]operation{out:=[]operation{};for ch:=0;ch<8;ch++{out=append(out,w(8,ch,"canonicalkeyoff"))};for _,r:=range [][2]int{{1,0},{15,0},{20,48},{24,0},{25,0},{25,128},{27,0}}{out=append(out,w(r[0],r[1],"publicglobal"))};for r:=32;r<256;r++{v:=0;if r>=96&&r<128{v=127};out=append(out,w(r,v,"fulltargetinit"))};return out}
func w(reg,value int,role string)operation{return operation{Kind:"write",Reg:reg,Value:value,Role:role}}
func d(count int,role string)operation{return operation{Kind:"delay",Count:count,Role:role}}
func encode(ops []operation)[]byte{b:=[]byte{};for _,o:=range ops{if o.Kind=="write"{b=append(b,1,byte(o.Reg),byte(o.Value))}else{b=append(b,2,byte(o.Count),byte(o.Count>>8))}};return append(b,0)}
func hash(b []byte)string{return fmt.Sprintf("%x",sha256.Sum256(b))}
